diff --git a/edlib/src/edlib.cpp b/edlib/src/edlib.cpp
index a77eef5..25b4545 100644
--- a/edlib/src/edlib.cpp
+++ b/edlib/src/edlib.cpp
@@ -1233,9 +1233,956 @@ static int obtainAlignmentHirschberg(
         const unsigned char* const target, const unsigned char* const rTarget, const int targetLength,
         const EqualityDefinition& equalityDefinition, const int alphabetLength, const int bestScore,
         unsigned char** const alignment, int* const alignmentLength) {
+
+    // Strategy: one banded forward pass (the optimal cost is known) keeps sparse checkpoint
+    // columns. Strips between checkpoints are then resolved right to left, starting from the end
+    // cell. A narrow strip is recomputed from its checkpoint with full storage and traced back
+    // directly; a wide strip gets a short backward pass from its exit cell, which is joined with
+    // the checkpoint column to find where the optimal path enters, and its sub-alignment is
+    // solved recursively. Myers' block kernel runs as a skewed wavefront over L consecutive
+    // columns so that L carry chains execute in parallel (AVX-512 / AVX2 when available).
+    typedef uint64_t U64;
+    typedef int64_t I64;
+    typedef U64 V4 __attribute__((vector_size(32)));
+    typedef U64 V8 __attribute__((vector_size(64)));
+    typedef uint32_t V8u __attribute__((vector_size(32)));
+
+    const int n = queryLength;
+    const int m = targetLength;
+    const int A = alphabetLength;
+    const int PADB = 16;                  // padding blocks around Peq and state arrays
+    const long STRIP_BUDGET = 64 * 1024;  // bytes of full storage for one directly traced strip
+    const long DMIN = 128;                 // narrowest strip worth tracing directly
+    const long SPLITW = 256;              // width of strips resolved by a backward pass and a split
+    const double AVX512_MIN_AREA = 100000.0;
+    const I64 WFA_ALPHA = 4;               // diagonal transition when cost^2 <= WFA_ALPHA * width
     *alignment = NULL;
     *alignmentLength = 0;
-    return EDLIB_STATUS_ERROR;
+    if (n <= 0 || m <= 0 || bestScore < 0) return EDLIB_STATUS_ERROR;
+
+    //---------------- CPU features ----------------//
+    bool haveAvx2 = false, haveAvx512 = false;
+    {
+        unsigned a, b, c, d;
+        __asm__ volatile("cpuid" : "=a"(a), "=b"(b), "=c"(c), "=d"(d) : "a"(0u), "c"(0u));
+        if (a >= 7) {
+            __asm__ volatile("cpuid" : "=a"(a), "=b"(b), "=c"(c), "=d"(d) : "a"(1u), "c"(0u));
+            const bool popcnt = ((c >> 23) & 1u) != 0;
+            if (((c >> 27) & 1u) && ((c >> 28) & 1u) && popcnt) {
+                unsigned xlo, xhi;
+                __asm__ volatile("xgetbv" : "=a"(xlo), "=d"(xhi) : "c"(0u));
+                (void)xhi;
+                if ((xlo & 6u) == 6u) {
+                    __asm__ volatile("cpuid" : "=a"(a), "=b"(b), "=c"(c), "=d"(d) : "a"(7u), "c"(0u));
+                    haveAvx2 = ((b >> 5) & 1u) != 0;
+                    haveAvx512 = haveAvx2 && ((b >> 16) & 1u) != 0 && (xlo & 0xE6u) == 0xE6u;
+                }
+            }
+        }
+    }
+    bool identityEq = true;
+    for (int x = 0; x < A && identityEq; x++)
+        for (int y = 0; y < A; y++)
+            if (equalityDefinition.areEqual(static_cast<unsigned char>(x), static_cast<unsigned char>(y)) != (x == y)) {
+                identityEq = false;
+                break;
+            }
+    const int AP = A <= 4 ? 4 : A;  // words per block in the interleaved Peq
+
+    auto popcSw = [](U64 x) -> int {
+        x = x - ((x >> 1) & 0x5555555555555555ull);
+        x = (x & 0x3333333333333333ull) + ((x >> 2) & 0x3333333333333333ull);
+        x = (x + (x >> 4)) & 0x0f0f0f0f0f0f0f0full;
+        return static_cast<int>((x * 0x0101010101010101ull) >> 56);
+    };
+
+    // Interleaved Peq: block b, symbol s at PI[b * AP + s]; valid for b in [-PADB, nbl + PADB).
+    // Row r has symbol seq[r]. Padding rows (>= len) match every symbol.
+    auto buildPeq = [&](U64* buf, const unsigned char* seq, int len, int nbl) -> U64* {
+        __builtin_memset(buf, 0, sizeof(U64) * static_cast<size_t>(nbl + 2 * PADB) * AP);
+        U64* PI = buf + static_cast<size_t>(PADB) * AP;
+        if (identityEq) {
+            for (int r = 0; r < len; r++) PI[(r >> 6) * AP + seq[r]] |= WORD_1 << (r & 63);
+        } else {
+            for (int r = 0; r < len; r++)
+                for (int s = 0; s < A; s++)
+                    if (equalityDefinition.areEqual(seq[r], static_cast<unsigned char>(s)))
+                        PI[(r >> 6) * AP + s] |= WORD_1 << (r & 63);
+        }
+        if (len & 63) {
+            const U64 pad = ~static_cast<U64>(0) << (len & 63);
+            for (int s = 0; s < AP; s++) PI[(nbl - 1) * AP + s] |= pad;
+        }
+        return PI;
+    };
+
+    //---------------- Banded wavefront pass ----------------//
+    // State arrays hold, per block, the vertical delta vectors (P, M) and the score of the block's
+    // last row (S) for the most recent column. Full storage keeps per step the vertical (P, M)
+    // and horizontal (PH, MH) delta vectors of every lane, which is all a traceback needs.
+    struct Pass {
+        const U64* PI;
+        int nbl;
+        int qlen;
+        const unsigned char* tsym;
+        int tlen;
+        int cend;  // columns >= cend are padding (garbage) and need no band updates
+        I64 k;
+        int mode;  // 0: global (end corner fixed); 1: free end row, score bound only
+        U64* P;
+        U64* M;
+        I64* S;
+        int fb, lb;    // band of the current state
+        int cfb, clb;  // computed range of the last stripe
+        U64* store;    // full storage (4*L words per step) or NULL
+        int* sinfo;    // per stripe: step base, fb, lb
+        long nsteps;
+        long cap;
+        int nstripes;
+        bool dead;
+    };
+
+    struct VOps {
+        static inline __attribute__((always_inline)) V4 rot(V4 v, U64 x) {
+            V4 b = V4{} + x;
+            return __builtin_shuffle(v, b, V4{4, 0, 1, 2});
+        }
+        static inline __attribute__((always_inline)) V8 rot(V8 v, U64 x) {
+            V8 b = V8{} + x;
+            return __builtin_shuffle(v, b, V8{8, 0, 1, 2, 3, 4, 5, 6});
+        }
+        static inline __attribute__((always_inline)) U64 rot(U64, U64 x) { return x; }
+        static inline __attribute__((always_inline)) U64 last(V4 v) { return v[3]; }
+        static inline __attribute__((always_inline)) U64 last(V8 v) { return v[7]; }
+        static inline __attribute__((always_inline)) U64 last(U64 v) { return v; }
+        static inline __attribute__((always_inline)) V4 unit(V4*, int l) {
+            V4 r = V4{} * 0;
+            r[l] = 1;
+            return r;
+        }
+        static inline __attribute__((always_inline)) V8 unit(V8*, int l) {
+            V8 r = V8{} * 0;
+            r[l] = 1;
+            return r;
+        }
+        static inline __attribute__((always_inline)) U64 unit(U64*, int) { return 1; }
+        static inline __attribute__((always_inline)) void put(U64* dst, V4 v) { __builtin_memcpy(dst, &v, sizeof v); }
+        static inline __attribute__((always_inline)) void put(U64* dst, V8 v) { __builtin_memcpy(dst, &v, sizeof v); }
+        static inline __attribute__((always_inline)) void put(U64* dst, U64 v) { *dst = v; }
+        static inline __attribute__((always_inline)) int pcHw(U64 x) {
+            U64 r;
+            __asm__("popcnt %1, %0" : "=r"(r) : "r"(x));
+            return static_cast<int>(r);
+        }
+    };
+    // Eq sources: 8 lanes gather, 4 lanes rolling permutes (alphabet <= 4), 1 lane direct load.
+    struct TagV8 {
+        typedef V8 V;
+        struct Eq {
+            V8 idx;
+            const U64* base;
+            long step;
+            inline __attribute__((always_inline)) void init(const U64* PI, const unsigned char* syms, int ap, int t0) {
+                base = PI;
+                step = ap;
+                U64 tmp[8];
+                for (int l = 0; l < 8; l++) tmp[l] = static_cast<U64>((static_cast<long>(t0) - l) * ap + syms[l]);
+                __builtin_memcpy(&idx, tmp, sizeof idx);
+            }
+            inline __attribute__((always_inline)) V8 next() {
+                V8 r;
+                __asm__("kxnorb %%k1, %%k1, %%k1\n\tvpxorq %[r], %[r], %[r]\n\tvpgatherqq (%[b],%[i],8), %[r]%{%%k1%}"
+                        : [r] "=&v"(r)
+                        : [b] "r"(base), [i] "v"(idx), "m"(*reinterpret_cast<const U64(*)[1 << 24]>(base - 8 * step))
+                        : "k1");
+                idx += static_cast<U64>(step);
+                return r;
+            }
+        };
+        static inline __attribute__((always_inline)) int pc(U64 x) { return VOps::pcHw(x); }
+    };
+    struct TagV4 {
+        typedef V4 V;
+        struct Eq {
+            V8u idx;
+            V4 q1, q2, q3;
+            const U64* PI;
+            int t;
+            inline __attribute__((always_inline)) void init(const U64* PI_, const unsigned char* syms, int, int t0) {
+                idx = V8u{2u * syms[0], 2u * syms[0] + 1u, 2u * syms[1], 2u * syms[1] + 1u,
+                          2u * syms[2], 2u * syms[2] + 1u, 2u * syms[3], 2u * syms[3] + 1u};
+                q1 = q2 = q3 = V4{} * 0;
+                PI = PI_;
+                t = t0;
+            }
+            inline __attribute__((always_inline)) V4 next() {
+                V8u blk;
+                __builtin_memcpy(&blk, PI + 4L * t, sizeof blk);
+                t++;
+                V4 q0 = reinterpret_cast<V4>(__builtin_shuffle(blk, idx));
+                V4 x = __builtin_shuffle(q0, q1, V4{0, 5, 2, 3});
+                V4 y = __builtin_shuffle(q2, q3, V4{0, 1, 2, 7});
+                V4 r = __builtin_shuffle(x, y, V4{0, 1, 6, 7});
+                q3 = q2;
+                q2 = q1;
+                q1 = q0;
+                return r;
+            }
+        };
+        static inline __attribute__((always_inline)) int pc(U64 x) { return VOps::pcHw(x); }
+    };
+    struct TagScalar {
+        typedef U64 V;
+        struct Eq {
+            const U64* p;
+            long step;
+            inline __attribute__((always_inline)) void init(const U64* PI, const unsigned char* syms, int ap, int t0) {
+                p = PI + static_cast<long>(t0) * ap + syms[0];
+                step = ap;
+            }
+            inline __attribute__((always_inline)) U64 next() {
+                const U64 r = *p;
+                p += step;
+                return r;
+            }
+        };
+        static inline int pc(U64 x) {
+            x = x - ((x >> 1) & 0x5555555555555555ull);
+            x = (x & 0x3333333333333333ull) + ((x >> 2) & 0x3333333333333333ull);
+            x = (x + (x >> 4)) & 0x0f0f0f0f0f0f0f0full;
+            return static_cast<int>((x * 0x0101010101010101ull) >> 56);
+        }
+    };
+
+    // Generic pass body over columns [c0, c1), stripes of L columns (V has L 64-bit lanes).
+    auto passBody = [&](auto tag, Pass& ps, int c0, int c1) __attribute__((always_inline)) {
+        typedef decltype(tag) Tag;
+        typedef typename Tag::V V;
+        const int L = static_cast<int>(sizeof(V) / sizeof(U64));
+        const V zero = V{} * 0;
+        const V one = zero + 1;
+        U64* const Pa = ps.P;
+        U64* const Ma = ps.M;
+        I64* const Sa = ps.S;
+        const U64* const PI = ps.PI;
+        auto deltaAbove = [&](U64 p, U64 mm, int bit) -> int {
+            if (bit >= 63) return 0;
+            return Tag::pc(p >> (bit + 1)) - Tag::pc(mm >> (bit + 1));
+        };
+        V laneIdx = zero;
+        {
+            U64 tmp[8];
+            for (int l = 0; l < L; l++) tmp[l] = static_cast<U64>(l);
+            __builtin_memcpy(&laneIdx, tmp, sizeof laneIdx);
+        }
+        int fb = ps.fb, lb = ps.lb;
+        for (int c = c0; c < c1; c += L) {
+            unsigned char syms[8];
+            for (int l = 0; l < L; l++) syms[l] = c + l < ps.cend ? ps.tsym[c + l] : 0;
+            ps.cfb = fb;
+            ps.clb = lb;
+            U64* st = NULL;
+            if (ps.store) {
+                if (ps.nsteps + (lb - fb + L) > ps.cap) {
+                    ps.dead = true;
+                    break;
+                }
+                ps.sinfo[3 * ps.nstripes] = static_cast<int>(ps.nsteps);
+                ps.sinfo[3 * ps.nstripes + 1] = fb;
+                ps.sinfo[3 * ps.nstripes + 2] = lb;
+                ps.nstripes++;
+                st = ps.store + ps.nsteps * 4 * L;
+                ps.nsteps += lb - fb + L;
+            }
+            typename Tag::Eq es;
+            es.init(PI, syms, static_cast<int>(AP), fb);
+            V vP = zero, vM = zero, vS = zero, hp = one, hn = zero;
+            auto step = [&](int t) __attribute__((always_inline)) {
+                const V xP = VOps::rot(vP, Pa[t]);
+                const V xM = VOps::rot(vM, Ma[t]);
+                const V xS = VOps::rot(vS, static_cast<U64>(Sa[t]));
+                const V eq = es.next();
+                const V Xv = eq | xM;
+                const V eq2 = eq | hn;
+                const V Xh = (((eq2 & xP) + xP) ^ xP) | eq2;
+                const V Ph = xM | ~(Xh | xP);
+                const V Mh = xP & Xh;
+                const V hpo = Ph >> 63, hno = Mh >> 63;
+                const V Ph1 = (Ph << 1) | hp;
+                const V Mh1 = (Mh << 1) | hn;
+                vP = Mh1 | ~(Xv | Ph1);
+                vM = Ph1 & Xv;
+                vS = xS + hpo - hno;
+                hp = hpo;
+                hn = hno;
+                if (st) {
+                    VOps::put(st, vP);
+                    VOps::put(st + L, vM);
+                    VOps::put(st + 2 * L, Ph);
+                    VOps::put(st + 3 * L, Mh);
+                    st += 4 * L;
+                }
+            };
+            int t = fb;
+            for (int j = 0; j < L; j++, t++) {
+                const V u = (laneIdx == (zero + static_cast<U64>(j))) & one;
+                hp |= u;
+                hn &= ~u;
+                step(t);
+            }
+            for (; t <= lb + L - 1; t++) {
+                Pa[t - L] = VOps::last(vP);
+                Ma[t - L] = VOps::last(vM);
+                Sa[t - L] = static_cast<I64>(VOps::last(vS));
+                step(t);
+            }
+            Pa[lb] = VOps::last(vP);
+            Ma[lb] = VOps::last(vM);
+            Sa[lb] = static_cast<I64>(VOps::last(vS));
+
+            // Band update from the stripe's last column (not needed after the last real column).
+            const int ce = c + L - 1;
+            if (ce >= ps.cend - 1) break;
+            const int oldlb = lb;
+            bool grow;
+            if (ps.mode == 0) {
+                const I64 D = static_cast<I64>(ps.qlen) - ps.tlen + ce;
+                // Minimum of F(r) + |D - r| over rows r in [r1, r2] of block b (exact, using the
+                // monotonicity of F(r) + r on rows below D and of F(r) - r on rows above D).
+                auto minFL = [&](int b, int b1, int b2) -> I64 {
+                    const I64 sb = Sa[b];
+                    const I64 top = 64LL * b;
+                    const I64 r1 = top + b1, r2 = top + b2;
+                    if (r2 <= D) return sb - deltaAbove(Pa[b], Ma[b], b2) + D - r2;
+                    if (r1 >= D) return sb - deltaAbove(Pa[b], Ma[b], b1) + r1 - D;
+                    return sb - deltaAbove(Pa[b], Ma[b], static_cast<int>(D - top));
+                };
+                // The path may still run along the virtual boundary row -1; then block 0 must stay.
+                const I64 dTop = D + 1;
+                const int keep = (fb == 0 && (ce + 1) + (dTop < 0 ? -dTop : dTop) <= ps.k) ? 0 : -1;
+                while (fb <= lb && fb != keep && minFL(fb, 0, 63) > ps.k) fb++;
+                while (lb >= fb && lb != keep && minFL(lb, 0, 63) > ps.k) lb--;
+                // The useful region moves down at most one row per column: grow only if one of the
+                // last 8 rows (the widest stripe) of the last block is useful.
+                grow = fb <= lb && minFL(lb, 56, 63) <= ps.k;
+            } else {
+                auto minF = [&](int b) -> I64 { return Sa[b] - Tag::pc(Pa[b] & ~WORD_1); };
+                const int keep = (fb == 0 && ce + 1 <= ps.k) ? 0 : -1;
+                while (fb <= lb && fb != keep && minF(fb) > ps.k) fb++;
+                while (lb >= fb && lb != keep && minF(lb) > ps.k) lb--;
+                grow = true;
+            }
+            if (fb > lb) {
+                ps.dead = true;
+                break;
+            }
+            if (grow && lb + 1 < ps.nbl) {
+                lb++;
+                if (lb > oldlb) {
+                    Pa[lb] = ~static_cast<U64>(0);
+                    Ma[lb] = 0;
+                    Sa[lb] = Sa[lb - 1] + 64;
+                }
+            }
+        }
+        ps.fb = fb;
+        ps.lb = lb;
+    };
+    auto pass8 = [&](Pass& ps, int c0, int c1) __attribute__((target("avx512f,avx2,popcnt"))) {
+        passBody(TagV8(), ps, c0, c1);
+    };
+    auto pass4 = [&](Pass& ps, int c0, int c1) __attribute__((target("avx2,popcnt"))) {
+        passBody(TagV4(), ps, c0, c1);
+    };
+    auto pass1 = [&](Pass& ps, int c0, int c1) { passBody(TagScalar(), ps, c0, c1); };
+    // Lane count of the fast kernel (no storage) and of the storage kernel.
+    // AVX-512 has a warm-up cost; it only pays off when the band area is large.
+    const double bandArea = static_cast<double>(m) * (static_cast<double>(bestScore) / 64.0 + 2.0);
+    const int LW = (haveAvx512 && (bandArea >= AVX512_MIN_AREA || !(haveAvx2 && A <= 4))) ? 8
+                                                                                          : (haveAvx2 && A <= 4 ? 4 : 1);
+    const int LS = (haveAvx2 && A <= 4) ? 4 : 1;
+    auto passL = [&](int L, Pass& ps, int c0, int c1) {
+        if (L == 8) pass8(ps, c0, c1);
+        else if (L == 4) pass4(ps, c0, c1);
+        else pass1(ps, c0, c1);
+    };
+    // Columns [c0, c1) with the fast kernel; the leading (c1 - c0) % LW columns run on the scalar one.
+    auto runPass = [&](Pass& ps, int c0, int c1) {
+        const int pro = (c1 - c0) % LW;
+        if (pro) pass1(ps, c0, c0 + pro);
+        if (!ps.dead && c0 + pro < c1) passL(LW, ps, c0 + pro, c1);
+    };
+    auto initState = [&](Pass& ps) {
+        // Column -1: F(i, -1) = i + 1.
+        I64 bottom;
+        if (ps.mode == 0) bottom = (ps.k + ps.qlen - ps.tlen - 2) / 2;
+        else bottom = ps.k - 1;
+        if (bottom < 0) bottom = 0;
+        I64 lbi = bottom / 64 + 1;
+        if (lbi > ps.nbl - 1) lbi = ps.nbl - 1;
+        ps.fb = 0;
+        ps.lb = static_cast<int>(lbi);
+        for (int b = 0; b <= ps.lb; b++) {
+            ps.P[b] = ~static_cast<U64>(0);
+            ps.M[b] = 0;
+            ps.S[b] = 64LL * (b + 1);
+        }
+        ps.cfb = ps.fb;
+        ps.clb = ps.lb;
+        ps.dead = false;
+        ps.store = NULL;
+        ps.sinfo = NULL;
+        ps.nsteps = 0;
+        ps.cap = 0;
+        ps.nstripes = 0;
+    };
+    auto setupPass = [&](Pass& ps, U64* stateBuf, const U64* PI, int nbl, int qlen, const unsigned char* tsym,
+                         int tlen, I64 k, int mode) {
+        ps.PI = PI;
+        ps.nbl = nbl;
+        ps.qlen = qlen;
+        ps.tsym = tsym;
+        ps.tlen = tlen;
+        ps.cend = tlen;
+        ps.k = k;
+        ps.mode = mode;
+        ps.P = stateBuf + PADB;
+        ps.S = reinterpret_cast<I64*>(stateBuf + (nbl + 2 * PADB) + PADB);
+        ps.M = stateBuf + 2 * (nbl + 2 * PADB) + PADB;
+        initState(ps);
+    };
+    auto stateWords = [&](int nbl) -> size_t { return 3 * static_cast<size_t>(nbl + 2 * PADB); };
+    auto peqWords = [&](int nbl) -> size_t { return static_cast<size_t>(nbl + 2 * PADB) * AP; };
+
+    //---------------- Output (written backwards) ----------------//
+    unsigned char* outBuf = static_cast<unsigned char*>(malloc(static_cast<size_t>(n) + m));
+    if (!outBuf) return EDLIB_STATUS_ERROR;
+    unsigned char* const outEnd = outBuf + static_cast<size_t>(n) + m;
+    bool failed = false;
+
+    //---------------- Full-storage strip: recompute + traceback ----------------//
+    // Bytes needed to store a strip of 'w' columns whose band never exceeds 'band' blocks.
+    auto stripBytes = [&](long w, long band) -> long {
+        const long stripes = (w + LS - 1) / LS;
+        return stripes * (band + LS - 1) * 4 * LS * 8 + stripes * 12;
+    };
+    // Recomputes columns [cs, cs + w) of a problem (query rows qa[0..qn), target ta) from the state
+    // in 'ps' (the state of column cs - 1, band ps.fb..ps.lb), then traces back from cell
+    // (i, cs + w - 1) with value v until the path leaves the strip on the left (column cs - 1)
+    // or reaches the top/left boundary. Returns the new (i, j, v) through references.
+    auto traceStrip = [&](Pass& ps, const unsigned char* qa, int cs, int w, long band, int& i, int& j, I64& v,
+                          unsigned char*& out) {
+        const int L = LS;
+        const int stripes = (w + L - 1) / L;
+        const long maxSteps = static_cast<long>(stripes) * (band + L - 1);
+        U64* store = static_cast<U64*>(malloc(sizeof(U64) * 4 * L * static_cast<size_t>(maxSteps)));
+        int* sinfo = static_cast<int*>(malloc(sizeof(int) * 3 * static_cast<size_t>(stripes)));
+        if (!store || !sinfo) {
+            free(store);
+            free(sinfo);
+            failed = true;
+            return;
+        }
+        ps.store = store;
+        ps.sinfo = sinfo;
+        ps.cap = maxSteps;
+        ps.nsteps = 0;
+        ps.nstripes = 0;
+        // Storage passes may run past the strip on padded (garbage) columns of the last stripe.
+        const int savedEnd = ps.cend;
+        ps.cend = cs + w;
+        passL(L, ps, cs, cs + stripes * L);
+        ps.cend = savedEnd;
+        ps.store = NULL;
+        if (ps.dead) {
+            free(store);
+            free(sinfo);
+            failed = true;
+            return;
+        }
+        const U64* PI = ps.PI;
+        const unsigned char* ta = ps.tsym;
+        const int lsh = L == 8 ? 3 : (L == 4 ? 2 : 0);
+        int curS = -1, sBase = 0, sFb = 0, sLb = -1;
+        // Entry for (block b, column c) or NULL when outside the stored band.
+        auto rec = [&](int b, int c) -> const U64* {
+            const int s = (c - cs) >> lsh, l = (c - cs) & (L - 1);
+            if (s != curS) {
+                curS = s;
+                sBase = sinfo[3 * s];
+                sFb = sinfo[3 * s + 1];
+                sLb = sinfo[3 * s + 2];
+            }
+            if (b < sFb || b > sLb) return NULL;
+            return store + static_cast<long>(sBase + b + l - sFb) * 4 * L + l;
+        };
+        while (i >= 0 && j >= cs) {
+            // Matches are always optimal moves: skip whole runs of them along the diagonal.
+            if (identityEq) {
+                while (i >= 7 && j - cs >= 7 && out - outBuf >= 8) {
+                    U64 xa, xb;
+                    __builtin_memcpy(&xa, qa + i - 7, 8);
+                    __builtin_memcpy(&xb, ta + j - 7, 8);
+                    const U64 x = xa ^ xb;
+                    const int k = x ? (__builtin_clzll(x) >> 3) : 8;
+                    const U64 zero8 = 0;
+                    __builtin_memcpy(out - 8, &zero8, 8);  // EDLIB_EDOP_MATCH == 0
+                    out -= k;
+                    i -= k;
+                    j -= k;
+                    if (k < 8) break;
+                }
+                while (i >= 0 && j >= cs && qa[i] == ta[j]) {
+                    *--out = EDLIB_EDOP_MATCH;
+                    i--;
+                    j--;
+                }
+            } else {
+                while (i >= 0 && j >= cs && ((PI[(i >> 6) * AP + ta[j]] >> (i & 63)) & 1)) {
+                    *--out = EDLIB_EDOP_MATCH;
+                    i--;
+                    j--;
+                }
+            }
+            if (i < 0 || j < cs) break;
+            const int b = i >> 6, r = i & 63;
+            const U64* e = rec(b, j);
+            if (!e) {
+                failed = true;
+                break;
+            }
+            const int dvi = static_cast<int>((e[0] >> r) & 1) - static_cast<int>((e[L] >> r) & 1);
+            int dhPrev;  // F(i-1, j) - F(i-1, j-1)
+            if (r > 0) {
+                dhPrev = static_cast<int>((e[2 * L] >> (r - 1)) & 1) - static_cast<int>((e[3 * L] >> (r - 1)) & 1);
+            } else {
+                const U64* e2 = b > 0 ? rec(b - 1, j) : NULL;
+                dhPrev = e2 ? static_cast<int>((e2[2 * L] >> 63) & 1) - static_cast<int>((e2[3 * L] >> 63) & 1) : 1;
+            }
+            // Diagonal (mismatch) if F(i-1, j-1) == v - 1, else up if F(i-1, j) == v - 1, else left.
+            const int diag = (dvi + dhPrev == 1);
+            const int up = (!diag) & (dvi == 1);
+            *--out = static_cast<unsigned char>(diag ? EDLIB_EDOP_MISMATCH : (up ? EDLIB_EDOP_INSERT : EDLIB_EDOP_DELETE));
+            i -= diag | up;
+            j -= diag | (!up);
+            v--;
+        }
+        free(store);
+        free(sinfo);
+    };
+
+    //---------------- Diagonal-transition solve for low-cost problems ----------------//
+    // Wavefronts W_s[k] hold, for diagonal k = j - i, the furthest target position j reachable
+    // with cost s (query rows i, target columns j consumed). Only diagonals that can still reach
+    // the final diagonal within the known cost are kept. Requires plain symbol equality.
+    auto wfaSolve = [&](const unsigned char* qa, int qn, const unsigned char* ta, int tn, int cost,
+                        unsigned char* out, bool& ok) -> unsigned char* {
+        ok = false;
+        const int kEnd = tn - qn;
+        const long cells = (static_cast<long>(cost) + 1) * (cost + 1) / 2 + 2L * (cost + 1) + 8;
+        int* wf = static_cast<int*>(malloc(sizeof(int) * static_cast<size_t>(cells)));
+        int* meta = static_cast<int*>(malloc(sizeof(int) * 3 * static_cast<size_t>(cost + 1)));  // base, lo, hi
+        if (!wf || !meta) {
+            free(wf);
+            free(meta);
+            return out;
+        }
+        const int NEG = -(1 << 30);
+        auto extend = [&](int i, int j) -> int {  // returns j after the run of matches from (i, j)
+            while (i + 8 <= qn && j + 8 <= tn) {
+                U64 xa, xb;
+                __builtin_memcpy(&xa, qa + i, 8);
+                __builtin_memcpy(&xb, ta + j, 8);
+                const U64 x = xa ^ xb;
+                if (x) {
+                    const int k = __builtin_ctzll(x) >> 3;
+                    return j + k;
+                }
+                i += 8;
+                j += 8;
+            }
+            while (i < qn && j < tn && qa[i] == ta[j]) {
+                i++;
+                j++;
+            }
+            return j;
+        };
+        long used = 0;
+        auto W = [&](int s, int k) -> int {
+            const int lo = meta[3 * s + 1], hi = meta[3 * s + 2];
+            if (k < lo || k > hi) return NEG;
+            return wf[meta[3 * s] + (k - lo)];
+        };
+        // Best predecessor offset for (s, k) and the move that produced it.
+        auto pred = [&](int s, int k, int& move) -> int {
+            int best = NEG;
+            move = -1;
+            const int a = W(s - 1, k);  // mismatch from the same diagonal
+            if (a != NEG && a < tn && a - k < qn && a + 1 > best) {
+                best = a + 1;
+                move = 0;
+            }
+            const int b = W(s - 1, k - 1);  // target symbol skipped (deletion)
+            if (b != NEG && b < tn && b + 1 > best) {
+                best = b + 1;
+                move = 1;
+            }
+            const int c = W(s - 1, k + 1);  // query symbol skipped (insertion)
+            if (c != NEG && c - (k + 1) < qn && c > best) {
+                best = c;
+                move = 2;
+            }
+            return best;
+        };
+        int sEnd = -1;
+        for (int sc = 0; sc <= cost; sc++) {
+            int lo, hi;
+            if (sc == 0) {
+                lo = hi = 0;
+            } else {
+                lo = meta[3 * (sc - 1) + 1] - 1;
+                hi = meta[3 * (sc - 1) + 2] + 1;
+            }
+            const int rem = cost - sc;
+            if (lo < kEnd - rem) lo = kEnd - rem;
+            if (hi > kEnd + rem) hi = kEnd + rem;
+            if (lo < -qn) lo = -qn;
+            if (hi > tn) hi = tn;
+            if (lo > hi || used + (hi - lo + 1) > cells) break;
+            meta[3 * sc] = static_cast<int>(used);
+            meta[3 * sc + 1] = lo;
+            meta[3 * sc + 2] = hi;
+            int* row = wf + used;
+            used += hi - lo + 1;
+            for (int k = lo; k <= hi; k++) {
+                int j;
+                if (sc == 0) {
+                    j = 0;
+                } else {
+                    int mv;
+                    j = pred(sc, k, mv);
+                    if (j == NEG) {
+                        row[k - lo] = NEG;
+                        continue;
+                    }
+                }
+                row[k - lo] = extend(j - k, j);
+            }
+            if (kEnd >= lo && kEnd <= hi && row[kEnd - lo] >= tn) {
+                sEnd = sc;
+                break;
+            }
+        }
+        if (sEnd == cost) {
+            // Traceback from (n, m) on diagonal kEnd.
+            int sc = sEnd, k = kEnd, j = tn;
+            while (true) {
+                int jStart, mv = -1;
+                if (sc == 0) jStart = 0;
+                else jStart = pred(sc, k, mv);
+                for (int x = j; x > jStart; x--) *--out = EDLIB_EDOP_MATCH;
+                if (sc == 0) break;
+                if (mv == 0) {
+                    *--out = EDLIB_EDOP_MISMATCH;
+                    j = jStart - 1;
+                } else if (mv == 1) {
+                    *--out = EDLIB_EDOP_DELETE;
+                    j = jStart - 1;
+                    k = k - 1;
+                } else {
+                    *--out = EDLIB_EDOP_INSERT;
+                    j = jStart;
+                    k = k + 1;
+                }
+                sc--;
+            }
+            ok = true;
+        }
+        free(wf);
+        free(meta);
+        return out;
+    };
+
+    //---------------- Recursive solve ----------------//
+    struct Checkpoint {
+        int col;       // checkpoint column (state after this column)
+        int fb, lb;    // band of the state
+        int nextW;     // width of the strip to the right of this checkpoint
+        bool direct;   // whether that strip is recomputed and traced directly
+        long band;     // band bound for a direct strip
+        I64 s0;        // score of the last row of block fb
+        U64* data;     // P[cnt], M[cnt]
+    };
+    // Solves NW of query rows [q0, q0+qn) against target columns [t0, t0+tn) with known cost,
+    // writing operations backwards ending at 'out'.
+    auto solve = [&](auto& self, int q0, int qn, int t0, int tn, I64 cost, unsigned char* out) -> unsigned char* {
+        if (failed) return out;
+        if (qn == 0) {
+            for (int x = 0; x < tn; x++) *--out = EDLIB_EDOP_DELETE;
+            return out;
+        }
+        if (tn == 0) {
+            for (int x = 0; x < qn; x++) *--out = EDLIB_EDOP_INSERT;
+            return out;
+        }
+        if (identityEq && cost * cost <= WFA_ALPHA * tn + 64) {
+            bool ok = false;
+            unsigned char* o2 = wfaSolve(query + q0, qn, target + t0, tn, static_cast<int>(cost), out, ok);
+            if (ok) return o2;
+        }
+        const int nbl = (qn + 63) / 64;
+        long band0 = (cost + 1 + 63) / 64 + 2;
+        if (band0 > nbl) band0 = nbl;
+        U64* peqBuf = static_cast<U64*>(malloc(sizeof(U64) * peqWords(nbl)));
+        U64* stateBuf = static_cast<U64*>(malloc(sizeof(U64) * stateWords(nbl)));
+        if (!peqBuf || !stateBuf) {
+            free(peqBuf);
+            free(stateBuf);
+            failed = true;
+            return out;
+        }
+        const U64* PI = buildPeq(peqBuf, query + q0, qn, nbl);
+        Pass ps;
+        setupPass(ps, stateBuf, PI, nbl, qn, target + t0, tn, cost, 0);
+        int i = qn - 1, j = tn - 1;
+        I64 v = cost;
+        if (stripBytes(tn, band0) <= STRIP_BUDGET || tn <= 16) {
+            traceStrip(ps, query + q0, 0, tn, band0, i, j, v, out);
+        } else {
+            // Forward pass with checkpoints; strip widths are chosen from the band at each checkpoint:
+            // narrow bands get strips that are recomputed with full storage, wide ones split strips.
+            // Strip width from the band at a checkpoint: a directly traced strip if its storage fits
+            // STRIP_BUDGET and the checkpoint density stays within CP_BUDGET, else a split strip.
+            auto stripWidth = [&](long band, bool& dir) -> int {
+                long w = 0;
+                if (stripBytes(DMIN, band) <= STRIP_BUDGET) {
+                    w = DMIN;
+                    while (w * 2 <= tn && stripBytes(w * 2, band) <= STRIP_BUDGET) w *= 2;
+                    dir = true;
+                } else {
+                    w = SPLITW;
+                    if (w > tn / 2) w = tn / 2;
+                    if (w < 1) w = 1;
+                    dir = false;
+                }
+                return static_cast<int>(w);
+            };
+            int cap = 16, ncp = 0;
+            Checkpoint* cps = static_cast<Checkpoint*>(malloc(sizeof(Checkpoint) * cap));
+            if (!cps) failed = true;
+            bool dir0 = false;
+            int col = stripWidth(band0, dir0);  // leftmost strip is [0, col)
+            if (col > tn) col = tn;
+            if (!failed && col < tn) runPass(ps, 0, col);
+            while (!failed && !ps.dead && col < tn) {
+                // checkpoint after column col - 1
+                const int sfb = ps.fb, slb = ps.lb;
+                const int cnt = slb - sfb + 1;
+                if (ncp == cap) {
+                    cap *= 2;
+                    Checkpoint* ncps = static_cast<Checkpoint*>(realloc(cps, sizeof(Checkpoint) * cap));
+                    if (!ncps) {
+                        failed = true;
+                        break;
+                    }
+                    cps = ncps;
+                }
+                Checkpoint& ck = cps[ncp];
+                ck.col = col - 1;
+                ck.fb = sfb;
+                ck.lb = slb;
+                ck.data = static_cast<U64*>(malloc(sizeof(U64) * 2 * static_cast<size_t>(cnt)));
+                if (!ck.data) {
+                    failed = true;
+                    break;
+                }
+                ncp++;
+                for (int b = sfb; b <= slb; b++) {
+                    ck.data[b - sfb] = ps.P[b];
+                    ck.data[cnt + b - sfb] = ps.M[b];
+                }
+                ck.s0 = ps.S[sfb];
+                ck.band = cnt + 3;
+                bool dir = false;
+                int w = stripWidth(ck.band, dir);
+                if (w > tn - col) w = tn - col;
+                ck.direct = dir;
+                ck.nextW = w;
+                if (col + w >= tn) break;  // the last strip needs no forward computation
+                runPass(ps, col, col + w);
+                col += w;
+            }
+            if (ps.dead) failed = true;
+            // Strip phase, right to left.
+            for (int x = ncp - 1; x >= 0 && !failed; x--) {
+                Checkpoint& ck = cps[x];
+                const int cs = ck.col + 1;  // strip [cs, j]
+                const int w = j - ck.col;
+                const int cnt = ck.lb - ck.fb + 1;
+                if (i < 0) break;
+                if (ck.direct) {
+                    // Restore the checkpoint state and recompute the strip with full storage.
+                    ps.fb = ck.fb;
+                    ps.lb = ck.lb;
+                    ps.dead = false;
+                    I64 sAcc = ck.s0;
+                    for (int b = ck.fb; b <= ck.lb; b++) {
+                        const U64 pv = ck.data[b - ck.fb], mv = ck.data[cnt + b - ck.fb];
+                        if (b > ck.fb) sAcc += popcSw(pv) - popcSw(mv);
+                        ps.P[b] = pv;
+                        ps.M[b] = mv;
+                        ps.S[b] = sAcc;
+                    }
+                    traceStrip(ps, query + q0, cs, w, ck.band, i, j, v, out);
+                } else {
+                    // Backward pass from (i, j) over the strip, joined with the checkpoint column.
+                    const U64* cP = ck.data;
+                    const U64* cM = ck.data + cnt;
+                    I64 Fmin = cs;  // boundary row -1 at column cs - 1
+                    {
+                        I64 sAcc = ck.s0;
+                        for (int b = 0; b < cnt; b++) {
+                            if (b > 0) sAcc += popcSw(cP[b]) - popcSw(cM[b]);
+                            const I64 lo = sAcc - popcSw(cP[b] & ~WORD_1);
+                            if (lo < Fmin) Fmin = lo;
+                        }
+                    }
+                    I64 kb = v - Fmin;
+                    if (kb < 0) kb = 0;
+                    long Hl = static_cast<long>(w) + kb + 1;
+                    if (Hl > i + 1) Hl = i + 1;
+                    const int H = static_cast<int>(Hl);
+                    const int nbb = (H + 63) / 64;
+                    U64* peqBuf2 = static_cast<U64*>(malloc(sizeof(U64) * peqWords(nbb)));
+                    U64* stateBuf2 = static_cast<U64*>(malloc(sizeof(U64) * stateWords(nbb)));
+                    if (!peqBuf2 || !stateBuf2) {
+                        free(peqBuf2);
+                        free(stateBuf2);
+                        failed = true;
+                        break;
+                    }
+                    // Reversed query from global row q0 + i upward; reversed target from column t0 + j leftward.
+                    const U64* PIb = buildPeq(peqBuf2, rQuery + (n - 1 - (q0 + i)), H, nbb);
+                    Pass pb;
+                    setupPass(pb, stateBuf2, PIb, nbb, H, rTarget + (m - 1 - (t0 + j)), w, kb, 1);
+                    runPass(pb, 0, w);
+                    if (pb.dead) {
+                        free(peqBuf2);
+                        free(stateBuf2);
+                        failed = true;
+                        break;
+                    }
+                    // Find row r (on column cs - 1) such that F(r, cs-1) + B(r+1) == v, where B(x) is the
+                    // cost of aligning query rows [x, i] with target columns [cs, j].
+                    const int bfb = pb.cfb, blb = pb.clb;
+                    auto Bv = [&](int x) -> I64 {
+                        const int ip = i - x;
+                        if (ip == -1) return w;
+                        if (ip < 0 || ip >= H) return static_cast<I64>(1) << 60;
+                        const int bb = ip >> 6, bit = ip & 63;
+                        if (bb < bfb || bb > blb) return static_cast<I64>(1) << 60;
+                        const int da = bit >= 63 ? 0 : popcSw(pb.P[bb] >> (bit + 1)) - popcSw(pb.M[bb] >> (bit + 1));
+                        return pb.S[bb] - da;
+                    };
+                    auto Fc = [&](int r) -> I64 {
+                        if (r == -1) return cs;
+                        if (r < 0 || r >= qn) return static_cast<I64>(1) << 60;
+                        const int bb = r >> 6, bit = r & 63;
+                        if (bb < ck.fb || bb > ck.lb) return static_cast<I64>(1) << 60;
+                        const int o = bb - ck.fb;
+                        I64 sb = ck.s0;
+                        for (int x2 = 1; x2 <= o; x2++) sb += popcSw(cP[x2]) - popcSw(cM[x2]);
+                        const int da = bit >= 63 ? 0 : popcSw(cP[o] >> (bit + 1)) - popcSw(cM[o] >> (bit + 1));
+                        return sb - da;
+                    };
+                    int rs = -2;
+                    // Candidate rows: r in [lo, hi] incrementally, plus r = -1 and r = i.
+                    int lo = 64 * ck.fb, hi = 64 * ck.lb + 63;
+                    if (hi > qn - 1) hi = qn - 1;
+                    const int xlo = i - static_cast<int>(std::min<long>(H - 1, 64L * blb + 63));
+                    const int xhi = i - 64 * bfb;
+                    if (lo < xlo - 1) lo = xlo - 1;
+                    if (hi > xhi - 1) hi = xhi - 1;
+                    if (hi > i - 1) hi = i - 1;
+                    if (lo < 0) lo = 0;
+                    if (lo <= hi) {
+                        I64 fcv = Fc(lo), bvv = Bv(lo + 1);
+                        for (int r = lo;; r++) {
+                            if (fcv + bvv == v) {
+                                rs = r;
+                                break;
+                            }
+                            if (r == hi) break;
+                            // advance: F(r+1) = F(r) + dv_cp(r+1); B(r+2) = B(r+1) - dv_b(i - r - 1)
+                            const int r1 = r + 1;
+                            const int o = (r1 >> 6) - ck.fb;
+                            fcv += static_cast<I64>((cP[o] >> (r1 & 63)) & 1) - static_cast<I64>((cM[o] >> (r1 & 63)) & 1);
+                            const int ip = i - r1;
+                            const int bb = ip >> 6;
+                            bvv -= static_cast<I64>((pb.P[bb] >> (ip & 63)) & 1) - static_cast<I64>((pb.M[bb] >> (ip & 63)) & 1);
+                        }
+                    }
+                    if (rs == -2 && Fc(-1) + Bv(0) == v) rs = -1;
+                    if (rs == -2 && Fc(i) + Bv(i + 1) == v) rs = i;
+                    free(peqBuf2);
+                    free(stateBuf2);
+                    if (rs == -2) {
+                        failed = true;
+                        break;
+                    }
+                    const I64 Fs = Fc(rs);
+                    out = self(self, q0 + rs + 1, i - rs, t0 + cs, w, v - Fs, out);
+                    i = rs;
+                    j = cs - 1;
+                    v = Fs;
+                }
+                free(ck.data);
+                ck.data = NULL;
+            }
+            for (int x = 0; x < ncp; x++) free(cps[x].data);
+            free(cps);
+            // Leftmost strip [0, j].
+            if (!failed && i >= 0 && j >= 0) {
+                const long bandL = band0;
+                if (stripBytes(j + 1, bandL) <= STRIP_BUDGET || j + 1 >= tn) {
+                    initState(ps);
+                    traceStrip(ps, query + q0, 0, j + 1, bandL, i, j, v, out);
+                } else {
+                    free(peqBuf);
+                    free(stateBuf);
+                    peqBuf = NULL;
+                    stateBuf = NULL;
+                    out = self(self, q0, i + 1, t0, j + 1, v, out);
+                    i = -1;
+                    j = -1;
+                }
+            }
+        }
+        free(peqBuf);
+        free(stateBuf);
+        if (failed) return out;
+        while (i >= 0) {
+            *--out = EDLIB_EDOP_INSERT;
+            i--;
+        }
+        while (j >= 0) {
+            *--out = EDLIB_EDOP_DELETE;
+            j--;
+        }
+        return out;
+    };
+
+    unsigned char* start = solve(solve, 0, n, 0, m, static_cast<I64>(bestScore), outEnd);
+    if (failed) {
+        free(outBuf);
+        return EDLIB_STATUS_ERROR;
+    }
+    const int len = static_cast<int>(outEnd - start);
+    __builtin_memmove(outBuf, start, static_cast<size_t>(len));
+    unsigned char* shrunk = static_cast<unsigned char*>(realloc(outBuf, static_cast<size_t>(len > 0 ? len : 1)));
+    *alignment = shrunk ? shrunk : outBuf;
+    *alignmentLength = len;
+    return EDLIB_STATUS_OK;
 }
